const inputItems = $input.all();

const sessions = inputItems.flatMap(item => {
  const value = item.json.data ?? item.json;

  if (Array.isArray(value)) {
    return value;
  }

  return [value];
});

const results = [];

for (const session of sessions) {
  if (!session.id) {
    throw new Error(
      `Invalid session. Received keys: ${Object.keys(session).join(", ")}`
    );
  }

  if (!Array.isArray(session.transcript)) {
    throw new Error(`Invalid transcript for ${session.id}`);
  }

  if (!Array.isArray(session.participants)) {
    throw new Error(`Missing participants for ${session.id}`);
  }

  const turns = session.transcript;
  const selectedIndices = new Set();

  for (let i = 0; i < Math.min(40, turns.length); i++) {
    selectedIndices.add(i);
  }

  for (let i = Math.max(0, turns.length - 20); i < turns.length; i++) {
    selectedIndices.add(i);
  }

  const sampledTranscript = [...selectedIndices]
    .sort((a, b) => a - b)
    .map(index => turns[index]);

  results.push({
    json: {
      ...session,
      original_turn_count: turns.length,
      sampled_turn_count: sampledTranscript.length,
      sampled_transcript: sampledTranscript
    }
  });
}

return results;

const classifications = $input.all();
const sessions = $('Validate and Sample Sessions').all();

if (classifications.length !== sessions.length) {
  throw new Error(
    `Item count mismatch: ${classifications.length} classifications, ${sessions.length} sessions`
  );
}

const allowedTypes = [
  'Client Coaching',
  'Internal Operations',
  'Sales Discovery',
  'Other'
];

return classifications.map((item, index) => {
  const response = item.json;
  const original = sessions[index].json;

  const sessionId = original.id;

  let raw = response.message?.content ?? response.response;

  if (typeof raw !== 'string') {
    throw new Error(`No classification content for ${sessionId}`);
  }

  let result;

  try {
    result = JSON.parse(raw);
  } catch {
    throw new Error(`Invalid classifier JSON for ${sessionId}: ${raw}`);
  }

  if (!allowedTypes.includes(result.meeting_type)) {
    throw new Error(
      `Invalid meeting_type for ${sessionId}: ${result.meeting_type}`
    );
  }

  const confidence = Number(result.confidence_score);

  if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) {
    throw new Error(`Invalid confidence score for ${sessionId}`);
  }

  const accepted =
    result.meeting_type === 'Client Coaching' &&
    confidence >= 0.80;

  return {
    json: {
      ...original,
      session_id: sessionId,
      classification: {
        meeting_type: result.meeting_type,
        confidence_score: confidence,
        summary: result.summary
      },
      firewall: {
        accepted,
        decision: accepted ? 'ACCEPTED' : 'REJECTED',
        reason: accepted
          ? null
          : result.meeting_type !== 'Client Coaching'
            ? 'Meeting is not Client Coaching'
            : 'Confidence score below 0.80'
      }
    }
  };
});

const session = $json;

const expectedCoach = "Dr. Sara Hegy";

// Find the expected coach in the participants list.
const coachParticipants = session.participants.filter(
  participant =>
    participant.name === expectedCoach &&
    participant.is_team_member === true
);

if (coachParticipants.length !== 1) {
  throw new Error(
    `${session.id}: Expected exactly one ${expectedCoach} participant, found ${coachParticipants.length}`
  );
}

// Extract only the coach's original spoken words.
const coachTurns = session.sampled_transcript.filter(
  turn => turn.speaker === expectedCoach
);

if (coachTurns.length === 0) {
  throw new Error(
    `${session.id}: No transcript turns found for ${expectedCoach}`
  );
}

return {
  json: {
    ...session,
    coach: expectedCoach,
    coach_turn_count: coachTurns.length,
    coach_dialogue: coachTurns.map(turn => ({
      timestamp: turn.timestamp,
      text: turn.text
    }))
  }
};

const session = $json;
const turns = session.coach_dialogue;

if (!Array.isArray(turns) || turns.length === 0) {
  throw new Error(`${session.session_id}: Missing coach dialogue`);
}

const dialogue = turns
  .map(turn => ({
    timestamp: turn.timestamp,
    text: String(turn.text || '').trim()
  }))
  .filter(turn => turn.text);

const fullText = dialogue.map(turn => turn.text).join('\n\n');
const chunks = [];
let remaining = fullText;

while (remaining.length > 700) {
  const target = remaining.length <= 1100
    ? Math.max(400, remaining.length - 700)
    : 600;

  let cut = -1;

  for (let i = Math.min(700, target + 60); i >= 400; i--) {
    if (/\s/.test(remaining[i])) {
      cut = i;
      break;
    }
  }

  if (cut < 0) {
    cut = remaining.lastIndexOf(' ', 700);
  }

  if (cut < 400) {
    cut = remaining.indexOf(' ', 400);
  }

  if (cut < 0 || cut > 700) {
    throw new Error('Unable to split coach dialogue safely');
  }

  chunks.push(remaining.slice(0, cut).trim());
  remaining = remaining.slice(cut).trim();
}

if (remaining) chunks.push(remaining);

const voiceDocuments = chunks.map((content, index) => ({
  stream_type: 'voice_sample',
  content,
  metadata: {
    session_id: session.session_id,
    coach: session.coach,
    chunk_index: index,
    timestamps: dialogue.map(turn => turn.timestamp),
    source: 'verbatim_coach_dialogue',
    final_short_chunk_exception: content.length < 400
  }
}));

return {
  json: {
    session_id: session.session_id,
    meeting_type: session.classification.meeting_type,
    framework_source: dialogue,
    voice_documents: voiceDocuments
  }
};

const response = $json;
const original = $('Prepare Dual Streams').all()[$itemIndex].json;

const raw = response.message?.content;

if (typeof raw !== "string") {
  throw new Error(`${original.session_id}: Missing Llama3 response`);
}

let parsed;

try {
  parsed = JSON.parse(raw);
} catch {
  throw new Error(`${original.session_id}: Invalid framework JSON`);
}

if (!Array.isArray(parsed.frameworks) || parsed.frameworks.length === 0) {
  throw new Error(`${original.session_id}: No frameworks extracted`);
}

const requiredFields = [
  "name",
  "core_principle",
  "diagnostic_questions",
  "steps",
  "decision_rules",
  "source_quotes"
];

const frameworks = parsed.frameworks.map((framework, index) => {
  for (const field of requiredFields) {
    if (framework[field] === null || framework[field] === undefined) {
      throw new Error(
        `${original.session_id}: Framework ${index} has missing field: ${field}`
      );
    }
  }

  if (!framework.name.trim() || !framework.core_principle.trim()) {
    throw new Error(
      `${original.session_id}: Framework ${index} has empty required text`
    );
  }

  if (!Array.isArray(framework.source_quotes) || framework.source_quotes.length === 0) {
    throw new Error(
      `${original.session_id}: Framework ${index} has no source quotes`
    );
  }

  return {
    ...framework,
    diagnostic_questions: Array.isArray(framework.diagnostic_questions)
      ? framework.diagnostic_questions
      : [],
    steps: Array.isArray(framework.steps) ? framework.steps : [],
    decision_rules: Array.isArray(framework.decision_rules)
      ? framework.decision_rules
      : []
  };
});

return {
  json: {
    session_id: original.session_id,
    framework_documents: frameworks.map((framework, index) => ({
      stream_type: "framework",
      content: JSON.stringify(framework),
      metadata: {
        session_id: original.session_id,
        coach: "Dr. Sara Hegy",
        framework_name: framework.name,
        framework_index: index,
        source: "llm_extracted_from_coach_dialogue"
      }
    })),
    voice_documents: original.voice_documents
  }
};

parameters.jsonBody:
={{
  {
    model: "llama3",
    stream: false,
    format: "json",
    messages: [
      {
        role: "system",
        content: `You are an expert coaching knowledge analyst.

Extract complete, reusable coaching frameworks from the coach's dialogue only.

For every framework:
- name: exact framework name.
- core_principle: explain the central idea in 1-3 complete sentences.
- diagnostic_questions: include every question the coach uses to diagnose the situation. Preserve the original wording.
- steps: extract the actual sequence of actions taught by the coach. Do not leave empty if the dialogue describes a process.
- decision_rules: capture explicit if/then decisions and conditions.
- source_quotes: include exact quotations from the coach that support the framework.

Important:
1. Do not omit important concepts or diagnostic questions.
2. Distinguish diagnostic questions from general statements.
3. Preserve distinctions such as neurological load versus operational drift.
4. Do not invent details.
5. Use empty arrays only when the dialogue contains no evidence for that field.
6. Return valid JSON with exactly one top-level key: frameworks.
7. Every framework must contain all six required fields. Never return null.`
      },
      {
        role: "user",
        content: JSON.stringify({
          session_id: $json.session_id,
          coach_dialogue: $json.framework_source
        })
      }
    ]
  }
}}

