const items = $input.all();

const documents = items.flatMap(item => [
  ...(item.json.framework_documents || []),
  ...(item.json.voice_documents || [])
]);

if (documents.length === 0) {
  throw new Error("No documents available for embedding");
}

return documents.map(doc => ({
  json: {
    session_id: doc.metadata.session_id,
    stream_type: doc.stream_type,
    content: doc.content,
    metadata: doc.metadata
  }
}));

const embeddingResponse = $json;

const original = $('Flatten Documents').all()[$itemIndex].json;

const embedding = embeddingResponse.embeddings?.[0];

if (!Array.isArray(embedding)) {
  throw new Error(`Missing embedding for item ${$itemIndex}`);
}

if (embedding.length !== 1024) {
  throw new Error(`Invalid dimensions: ${embedding.length}`);
}

return {
  json: {
    ...original,
    embedding
  }
};
